    "question_type": "Bài tập tính toán",
    "prompt": "Cho biến ngẫu nhiên hai chiều (X, Y) có hàm mật độ đồng thời f(x, y) = a(x^2 + y^2) khi 0 <= x, y <= 1 và f(x, y) = 0 ở ngoài. Tìm hệ số a và hàm mật độ biên f_X(x):",
    "options": [
      "A. $a = \\frac{3}{2};\\quad  f_X(x) = (\\frac{3}{2})x^2 + \\frac{1}{2}$",
      "B. $a = \\frac{3}{2};\\quad  f_X(x) = 3x^2 + 1$",
      "C. $a = 1;\\quad  f_X(x) = x^2 + \\frac{1}{2}$",
      "D. $a = 2;\\quad  f_X(x) = 2x^2 + \\frac{2}{3}$"
    ],
